<?php
/**
 * Starts Page Builder Sandwich: every class, the boot calls, the AI core, the admin kit and the
 * premium layer.
 *
 * Read by bootstrap.php through Cli_Start::start(): at once, or — in a WP-CLI command — on WP-CLI's
 * `after_wp_load`, with every already-fired action replayed (class-cli-start.php, stage PERF3).
 *
 * @package ZinnDigital\PBS
 */

declare( strict_types = 1 );

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

// HOSTDISC — the hosting-customer Pro discount card (generated by wp/bin/build-promo.php).
require_once __DIR__ . '/class-pro-discount.php';
require_once __DIR__ . '/core/load.php';
require_once __DIR__ . '/blocks/load.php';
require_once __DIR__ . '/design/icons/load.php';
require_once __DIR__ . '/migrate/load.php';
require_once __DIR__ . '/design/load.php';
require_once __DIR__ . '/assets/load.php';
require_once __DIR__ . '/design/globals/load.php';
require_once __DIR__ . '/workflow/load.php';
// Lane L12 P12: AI inside the builder (free part).
require_once __DIR__ . '/ai/load.php';
// Lane L12 P13: SEO plugins' analysis sees the rendered page (free part).
require_once __DIR__ . '/seo/load.php';
// Lane L12 P16: the developer platform (public PHP API for add-ons).
require_once __DIR__ . '/dev/load.php';
require_once __DIR__ . '/design/a11y/load.php';
// Lane L11 P11: the website-kit library, its importer and the translated section patterns.
require_once __DIR__ . '/cloud/load.php';
// Lane PLUGIN-MCP: the abilities (WordPress Abilities API) and this site's own MCP server, through
// the shared MCP kit (wp/packages/zinn-mcp-kit) and the bundled WordPress MCP adapter.
require_once __DIR__ . '/mcp-kit/load.php';

\ZinnDigital\PBS\Plugin::boot();
\ZinnDigital\PBS\Mcp\Abilities::boot();

/*
 * The shared AI core (wp/packages/zinn-ai-core, rendered into ai-core/ by wp/bin/build-ai-core.php).
 * If another plugin on the site carries its own copy, the copies agree on one settings screen and
 * one set of keys by themselves; see ai-core/class-core.php.
 */
require_once __DIR__ . '/ai-core/load.php';
\ZinnDigital\PBS\AiCore\Core::boot(
	array(
		'slug'     => 'page-builder-sandwich',
		'name'     => 'Page Builder Sandwich',
		'pro'      => static fn(): bool => \ZinnDigital\PBS\Licensing::can_use_premium(),
		// Every AI request this plugin sends passes through `pbsw_ai_messages` ($messages, $context:
		// task, purpose, provider, model, user); the premium brand kit adds the brand (pbs-d10).
		'messages' => static fn( array $messages, array $context ): array => (array) apply_filters( 'pbsw_ai_messages', $messages, $context ),
	)
);

/*
 * The shared admin kit (wp/packages/zinn-admin-kit, rendered into admin-kit/ by
 * wp/bin/build-admin-kit.php): the shell around the settings screen — overview, plans, add-ons,
 * help and support, the setup wizard. Our own screens only; it adds nothing to other admin pages.
 */
require_once __DIR__ . '/admin-kit/load.php';
\ZinnDigital\PBS\AdminKit\Kit::boot(
	array(
		'slug'           => 'page-builder-sandwich',
		'name'           => 'Page Builder Sandwich',
		'version'        => PBSW_VERSION,
		'fs'             => 'pbsw_fs',
		'menu_slug'      => \ZinnDigital\PBS\Admin::SLUG,
		'rest_namespace' => \ZinnDigital\PBS\Rest::NAMESPACE,
		'file'           => PBSW_FILE,
	)
);

/*
 * ⛔⛔ THE PREMIUM LAYER LOADS ONLY WHEN ITS FILE IS PRESENT AND THE LICENCE ALLOWS IT.
 *
 * The free package (house and licensing-service alike) drops the whole premium-only directory,
 * so the first test fails there and nothing else runs. The directory name is assembled from two
 * halves so the premium-only token never appears in a file that ships in the free package: that
 * file must reach the free zip byte-for-byte unchanged (CONTRACT §3, docs/adr/0032).
 */
$pbsw_premium_entry = __DIR__ . '/pro_' . '_premium_only/class-pro.php'; // phpcs:ignore Generic.Strings.UnnecessaryStringConcat.Found -- deliberate split, see above.
if ( is_readable( $pbsw_premium_entry ) ) {
	require_once $pbsw_premium_entry;
	\ZinnDigital\PBS\Pro\Pro::licence();
	if ( \ZinnDigital\PBS\Licensing::can_use_premium() ) {
		\ZinnDigital\PBS\Pro\Pro::boot();
	}
}
unset( $pbsw_premium_entry );
